css:
.petrol-sim-container {
    padding: 24px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e0e6f0;
}
.petrol-sim-container * { box-sizing: border-box; }
.petrol-sim-header {
    border-left: 4px solid #00ff88;
    padding: 20px 28px;
    margin-bottom: 24px;
    background: rgba(0,255,136,0.05);
}
.petrol-sim-header h1 {
    color: #00ff88;
    font-size: 1.5rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    margin: 0 0 4px 0;
}
.petrol-sim-header p {
    color: #6b7280;
    font-size: 0.85rem;
    margin: 0;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}
.petrol-sim-period-counter {
    text-align: center;
    font-size: 1rem;
    color: #a0aec0;
    margin-bottom: 20px;
}
.petrol-sim-period-counter span { margin: 0 4px; }
.petrol-sim-briefing {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px;
    margin-bottom: 24px;
    color: #cbd5e0;
    line-height: 1.6;
    font-size: 0.95rem;
}
.petrol-sim-valuefuel {
    display: none;
    background: rgba(255,165,0,0.1);
    border: 1px solid rgba(255,165,0,0.4);
    border-radius: 8px;
    padding: 14px 18px;
    text-align: center;
    color: #ffa500;
    font-weight: 600;
    margin-bottom: 20px;
    font-size: 1rem;
}
.petrol-sim-stations {
    display: flex;
    align-items: flex-start;
    justify-content: center;
    gap: 20px;
    margin-bottom: 24px;
}
.petrol-sim-station {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 12px;
    padding: 24px;
    text-align: center;
    flex: 1;
    max-width: 300px;
    position: relative;
}
.petrol-sim-player-station { border-top: 3px solid #00ff88; }
.petrol-sim-rival-station { border-top: 3px solid #ff4757; }
.petrol-sim-station-name {
    font-size: 1.1rem;
    font-weight: 700;
    margin-bottom: 12px;
}
.petrol-sim-player-station .petrol-sim-station-name { color: #00ff88; }
.petrol-sim-rival-station .petrol-sim-station-name { color: #ff4757; }
.petrol-sim-price-tag {
    font-size: 2.4rem;
    font-weight: 700;
    color: #ffffff;
    background: rgba(255,255,255,0.05);
    border-radius: 8px;
    padding: 14px;
}
.petrol-sim-vs {
    font-size: 1.6rem;
    font-weight: 700;
    color: #4a5568;
    flex-shrink: 0;
    padding-top: 40px;
}
.petrol-sim-speech-bubble {
    background: rgba(255,71,87,0.1);
    border: 1px solid rgba(255,71,87,0.3);
    border-radius: 12px;
    padding: 10px 14px;
    font-size: 0.85rem;
    color: #ffa0a8;
    font-style: italic;
    min-height: 40px;
    margin-top: 12px;
}
.petrol-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.petrol-sim-kpi-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px 16px;
    text-align: center;
    position: relative;
    overflow: hidden;
}
.petrol-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #00ff88, #00bfff);
}
.petrol-sim-kpi-rival::before {
    background: linear-gradient(90deg, #ff4757, #ff6b81);
}
.petrol-sim-kpi-round::before {
    background: linear-gradient(90deg, #ffa500, #ffd700);
}
.petrol-sim-kpi-label {
    color: #6b7280;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 8px;
}
.petrol-sim-kpi-value {
    font-size: 1.8rem;
    font-weight: 700;
    color: #00ff88;
}
.petrol-sim-kpi-rival .petrol-sim-kpi-value { color: #ff4757; }
.petrol-sim-kpi-round .petrol-sim-kpi-value { color: #ffd700; }
.petrol-sim-cma-alarm {
    display: none;
    background: rgba(255,0,0,0.15);
    border: 2px solid #ff0000;
    border-radius: 8px;
    padding: 16px;
    text-align: center;
    color: #ff4757;
    font-weight: 700;
    font-size: 1.1rem;
    margin-bottom: 24px;
    animation: petrol-sim-flash 0.5s ease-in-out 3;
}
@keyframes petrol-sim-flash {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.3; }
}
.petrol-sim-controls {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 24px;
    margin-bottom: 24px;
}
.petrol-sim-controls h3 {
    color: #e0e6f0;
    font-size: 1rem;
    margin-bottom: 16px;
    margin-top: 0;
}
.petrol-sim-choice-buttons {
    display: flex;
    gap: 12px;
    margin-bottom: 16px;
}
.petrol-sim-choice-btn {
    flex: 1;
    padding: 16px;
    border-radius: 8px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
    border: 2px solid #2d3f55;
    background: #0a0f1e;
    color: #e0e6f0;
    font-family: inherit;
}
.petrol-sim-hold-btn:hover {
    border-color: #00ff88;
    background: rgba(0,255,136,0.08);
}
.petrol-sim-undercut-btn:hover {
    border-color: #ff4757;
    background: rgba(255,71,87,0.08);
}
.petrol-sim-hold-btn.petrol-sim-selected {
    border-color: #00ff88;
    background: rgba(0,255,136,0.15);
    color: #00ff88;
    box-shadow: 0 0 16px rgba(0,255,136,0.2);
}
.petrol-sim-undercut-btn.petrol-sim-selected {
    border-color: #ff4757;
    background: rgba(255,71,87,0.15);
    color: #ff4757;
    box-shadow: 0 0 16px rgba(255,71,87,0.2);
}
.petrol-sim-cartel-option {
    background: rgba(255,165,0,0.08);
    border: 1px solid rgba(255,165,0,0.3);
    border-radius: 8px;
    padding: 12px 16px;
    margin-bottom: 16px;
    color: #ffa500;
    font-size: 0.9rem;
}
.petrol-sim-cartel-option input[type="checkbox"] { margin-right: 8px; }
.petrol-sim-selected-choice {
    color: #a0aec0;
    margin-bottom: 16px;
    font-size: 0.9rem;
}
.petrol-sim-submit-btn {
    width: 100%;
    padding: 14px;
    background: linear-gradient(135deg, #00ff88, #00bfff) !important;
    border: none !important;
    border-radius: 8px !important;
    color: #0a0f1e !important;
    font-weight: 700;
    font-size: 1rem;
    cursor: pointer;
    margin-bottom: 8px;
    transition: opacity 0.2s ease;
}
.petrol-sim-submit-btn:hover { opacity: 0.9; }
.petrol-sim-undo-btn { width: 100%; color: #a0aec0; border-color: #2d3f55; }
.petrol-sim-matrix {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px;
    margin-bottom: 24px;
    overflow-x: auto;
}
.petrol-sim-matrix h3 {
    color: #a0aec0;
    font-size: 0.85rem;
    margin-bottom: 14px;
    margin-top: 0;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.petrol-sim-matrix-table {
    width: 100%;
    border-collapse: collapse;
}
.petrol-sim-matrix-table th,
.petrol-sim-matrix-table td {
    padding: 14px 18px;
    text-align: center;
    border: 1px solid #1f2d3d;
}
.petrol-sim-matrix-table th {
    background: #0a0f1e;
    color: #a0aec0;
    font-size: 0.85rem;
    font-weight: 600;
}
.petrol-sim-matrix-table td {
    background: #0d1520;
    color: #e0e6f0;
    font-size: 0.95rem;
    transition: all 0.3s ease;
}
.petrol-sim-cell-active {
    background: rgba(0,255,136,0.15) !important;
    border-color: #00ff88 !important;
    color: #00ff88 !important;
    font-weight: 700;
    box-shadow: inset 0 0 16px rgba(0,255,136,0.1);
}
.petrol-sim-chart {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px;
    margin-bottom: 24px;
    height: 320px;
}
.petrol-sim-history {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 20px;
    overflow-x: auto;
}
.petrol-sim-container .table { color: #e0e6f0; }
.petrol-sim-container .table th { color: #a0aec0; border-color: #1f2d3d; }
.petrol-sim-container .table td { border-color: #1f2d3d; }
.petrol-sim-container .table-striped tbody tr:nth-of-type(odd) { background-color: rgba(255,255,255,0.03); }
@media (max-width: 768px) {
    .petrol-sim-container { padding: 14px; }
    .petrol-sim-stations { flex-direction: column; align-items: stretch; }
    .petrol-sim-station { max-width: 100%; }
    .petrol-sim-vs { padding-top: 0; text-align: center; }
    .petrol-sim-choice-buttons { flex-direction: column; }
    .petrol-sim-kpi-grid { grid-template-columns: 1fr; }
    .petrol-sim-price-tag { font-size: 1.8rem; }
}

